function Update-ModeUI {
    if ($script:BeginnerMode) {
        $LblBeginner.Foreground = $Window.FindResource('TextMain'); $LblBeginner.FontWeight = 'SemiBold'
        $LblAdvanced.Foreground = $Window.FindResource('TextDim'); $LblAdvanced.FontWeight = 'Normal'
    } else {
        $LblAdvanced.Foreground = $Window.FindResource('TextMain'); $LblAdvanced.FontWeight = 'SemiBold'
        $LblBeginner.Foreground = $Window.FindResource('TextDim'); $LblBeginner.FontWeight = 'Normal'
    }
}
function Set-BeginnerMode {
    param([bool]$Enabled)
    $script:BeginnerMode = $Enabled
    $Settings.beginnerMode = $Enabled
    Save-Settings
    Update-ModeUI
    Update-HighRiskCheckbox
    Remove-HiddenHighRiskSelection
    Render-Tweaks -Category $CategoryList.SelectedItem -Filter $TxtSearch.Text
    Write-Log ("Modo {0} ativado." -f $(if ($Enabled) { 'Iniciante' } else { 'Avançado' }))
}

# Itens de risco Alto já marcados são desmarcados quando passam a ficar ocultos,
# para nunca aplicar algo que o usuário não consegue ver na lista.
function Remove-HiddenHighRiskSelection {
    if (-not (Test-HighRiskHidden)) { return }
    $highIds = @($AllTweaks | Where-Object { $_.risk -eq 'Alto' } | Select-Object -ExpandProperty id)
    $removed = 0
    foreach ($id in $highIds) { if ($SelectedIds.Remove($id)) { $removed++ } }
    if ($removed -gt 0) { Write-Log "$removed tweak(s) de risco Alto desmarcados ao ocultá-los." 'WARN' }
}

# Caixa 'Mostrar risco Alto': no Modo Avançado fica marcada e travada (tudo é exibido);
# no Iniciante o usuário decide. $script:SyncingHighRisk evita reentrância dos eventos.
$script:SyncingHighRisk = $false
function Update-HighRiskCheckbox {
    $script:SyncingHighRisk = $true
    try {
        if ($script:BeginnerMode) {
            $ChkShowHighRisk.IsEnabled = $true
            $ChkShowHighRisk.IsChecked = $script:ShowHighRisk
            $ChkShowHighRisk.ToolTip = "Exibe também os ajustes marcados como risco Alto (segurança, Defender, Edge, OneDrive etc.). Leia a descrição de cada um antes de marcar."
        } else {
            $ChkShowHighRisk.IsChecked = $true
            $ChkShowHighRisk.IsEnabled = $false
            $ChkShowHighRisk.ToolTip = "No Modo Avançado todos os ajustes, incluindo os de risco Alto, são sempre exibidos."
        }
    } finally { $script:SyncingHighRisk = $false }
}
function Set-ShowHighRisk {
    param([bool]$Enabled, [switch]$Confirm)
    if ($Enabled -and $Confirm) {
        $msg = "Os ajustes de risco Alto mexem em segurança (Defender, Spectre/Meltdown, VBS), removem programas inteiros (Edge, OneDrive com arquivos) ou pausam atualizações por anos.`n`n" +
               "Eles ficam visíveis, mas NADA é aplicado até você marcar e clicar em Aplicar. Leia a descrição de cada um.`n`nMostrar os ajustes de risco Alto?"
        $r = [System.Windows.MessageBox]::Show($Window, $msg, 'Win-Slim Suite - Risco Alto', 'YesNo', 'Warning')
        if ($r -ne 'Yes') { Update-HighRiskCheckbox; return }
    }
    $script:ShowHighRisk = $Enabled
    $Settings.showHighRisk = $Enabled
    Save-Settings
    Update-HighRiskCheckbox
    Remove-HiddenHighRiskSelection
    Render-Tweaks -Category $CategoryList.SelectedItem -Filter $TxtSearch.Text
    Write-Log ("Exibição de risco Alto: {0}." -f $(if ($Enabled) { 'ligada' } else { 'desligada' }))
}

$ChkAdvancedMode.IsChecked = -not $script:BeginnerMode
Update-ModeUI
Update-HighRiskCheckbox
$ChkAdvancedMode.Add_Checked({ Invoke-Safe -Context 'ativar o Modo Avançado' -Action { Set-BeginnerMode -Enabled $false } })
$ChkAdvancedMode.Add_Unchecked({ Invoke-Safe -Context 'ativar o Modo Iniciante' -Action { Set-BeginnerMode -Enabled $true } })
$ChkShowHighRisk.Add_Checked({ if (-not $script:SyncingHighRisk) { Invoke-Safe -Context 'mostrar os ajustes de risco Alto' -Action { Set-ShowHighRisk -Enabled $true -Confirm } } })
$ChkShowHighRisk.Add_Unchecked({ if (-not $script:SyncingHighRisk) { Invoke-Safe -Context 'ocultar os ajustes de risco Alto' -Action { Set-ShowHighRisk -Enabled $false } } })
$BtnShowHighRisk.Add_Click({ Invoke-Safe -Context 'mostrar os ajustes de risco Alto' -Action { Set-ShowHighRisk -Enabled $true -Confirm } })

