$script:OnboardingSteps = @(
    [pscustomobject]@{
        Title = 'Antes de tudo: o ponto de restauração'
        Body  = "O Win-Slim cria um ponto de restauração do Windows antes de aplicar qualquer coisa (a opção fica marcada no topo da janela).`n`nÉ como uma foto do seu sistema: se algo não ficar do seu gosto, você volta tudo pelo botão Rollback aqui no programa ou pela Restauração do Sistema do Windows.`n`nRecomendação: deixe essa opção sempre marcada."
    }
    [pscustomobject]@{
        Title = 'Entendendo as cores de risco'
        Body  = "Cada ajuste tem uma etiqueta colorida:`n`n• Baixo (verde): seguro, pode aplicar sem medo.`n• Médio (amarelo): leia a descrição antes — pode não servir para todo mundo.`n• Alto (vermelho): mexe em segurança ou pode causar problemas. Fica escondido no início.`n`nVocê começa no Modo Iniciante: nomes simples e sem itens de risco Alto. Para vê-los, marque 'Mostrar risco Alto' na aba Avançado ou troque para o Modo Avançado no topo da janela."
    }
    [pscustomobject]@{
        Title = 'O que acontece ao clicar em "Aplicar"'
        Body  = "1. O programa cria o ponto de restauração.`n2. Guarda o valor atual de cada configuração que vai mudar (para poder desfazer).`n3. Aplica os ajustes marcados, um por um, mostrando o progresso.`n4. Reinicia a barra de tarefas para as mudanças aparecerem.`n`nDepois é só reiniciar o computador. Quer ver antes o que seria feito sem mudar nada? Marque 'Modo Simulação' na aba Avançado."
    }
)

function Show-Onboarding {
    $obXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Bem-vindo ao Win-Slim Suite" Width="560" SizeToContent="Height" MinHeight="300"
        WindowStartupLocation="CenterOwner" ResizeMode="NoResize" ShowInTaskbar="False"
        Background="#171A21" FontFamily="Segoe UI" Foreground="#E7E9EE">
    <Grid Margin="28,24,28,20">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        <TextBlock x:Name="ObStep" Grid.Row="0" Foreground="#FF8C42" FontSize="11.5" FontWeight="Bold"/>
        <TextBlock x:Name="ObTitle" Grid.Row="1" FontSize="19" FontWeight="Bold" TextWrapping="Wrap" Margin="0,6,0,12"/>
        <TextBlock x:Name="ObBody" Grid.Row="2" FontSize="13" TextWrapping="Wrap" Foreground="#C9CDD6" LineHeight="20" MinHeight="150"/>
        <Grid Grid.Row="3" Margin="0,22,0,0">
            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                <Ellipse x:Name="Dot1" Width="9" Height="9" Margin="0,0,6,0" Fill="#FF8C42"/>
                <Ellipse x:Name="Dot2" Width="9" Height="9" Margin="0,0,6,0" Fill="#2A2F3A"/>
                <Ellipse x:Name="Dot3" Width="9" Height="9" Margin="0,0,6,0" Fill="#2A2F3A"/>
            </StackPanel>
            <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
                <Button x:Name="ObSkip" Content="Pular" Padding="12,6" Margin="0,0,8,0" Background="Transparent" Foreground="#9AA0AC" BorderThickness="0" Cursor="Hand"/>
                <Button x:Name="ObBack" Content="Voltar" Padding="14,6" Margin="0,0,8,0" Background="#1E222B" Foreground="#E7E9EE" BorderBrush="#2A2F3A" Cursor="Hand"/>
                <Button x:Name="ObNext" Content="Próximo" Padding="22,6" Background="#FF8C42" Foreground="#1A0F08" FontWeight="SemiBold" BorderThickness="0" Cursor="Hand" IsDefault="True"/>
            </StackPanel>
        </Grid>
    </Grid>
</Window>
'@
    $ob = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$obXaml)))
    if ($Window.IsLoaded) { $ob.Owner = $Window } else { $ob.WindowStartupLocation = 'CenterScreen' }
    $steps = $script:OnboardingSteps
    $state = @{ Index = 0 }
    $ctl = @{
        Step = $ob.FindName('ObStep'); Title = $ob.FindName('ObTitle'); Body = $ob.FindName('ObBody')
        Back = $ob.FindName('ObBack'); Next = $ob.FindName('ObNext'); Skip = $ob.FindName('ObSkip')
        Dots = @($ob.FindName('Dot1'), $ob.FindName('Dot2'), $ob.FindName('Dot3'))
    }
    $render = {
        $i = $state.Index
        $ctl.Step.Text = "PASSO $($i + 1) DE $($steps.Count)"
        $ctl.Title.Text = $steps[$i].Title
        $ctl.Body.Text = $steps[$i].Body
        $ctl.Back.Visibility = if ($i -eq 0) { 'Hidden' } else { 'Visible' }
        $ctl.Next.Content = if ($i -eq $steps.Count - 1) { 'Começar' } else { 'Próximo' }
        for ($d = 0; $d -lt $ctl.Dots.Count; $d++) { $ctl.Dots[$d].Fill = if ($d -eq $i) { '#FF8C42' } else { '#2A2F3A' } }
    }.GetNewClosure()
    $ctl.Next.Add_Click({
        if ($state.Index -ge $steps.Count - 1) { $ob.DialogResult = $true; $ob.Close(); return }
        $state.Index++; & $render
    }.GetNewClosure())
    $ctl.Back.Add_Click({ if ($state.Index -gt 0) { $state.Index--; & $render } }.GetNewClosure())
    $ctl.Skip.Add_Click({ $ob.DialogResult = $false; $ob.Close() }.GetNewClosure())
    & $render
    $ob.ShowDialog() | Out-Null
    $Settings.onboardingDone = $true
    Save-Settings
    Write-Log 'Onboarding exibido.'
}
$BtnShowOnboarding.Add_Click({ Invoke-Safe -Context 'mostrar a introdução' -Action { Show-Onboarding } })
if (-not [bool]$Settings.onboardingDone) {
