# ============================================================================
# 13. APLICAR / ROLLBACK
# ============================================================================
function Get-SelectedSimpleIds { return @($SelectedIds) }
function Get-SelectedLeveledIds { return @($LevelSelections.GetEnumerator() | Where-Object { $_.Value -gt 0 } | Select-Object -ExpandProperty Key) }

function Run-Batch {
    param([switch]$Undo)
    $selectedSimple = Get-SelectedSimpleIds
    $selectedLeveled = Get-SelectedLeveledIds

    if ($selectedSimple.Count -eq 0 -and $selectedLeveled.Count -eq 0) {
        [System.Windows.MessageBox]::Show("Nenhum tweak selecionado.", "Win-Slim Suite", 'OK', 'Information') | Out-Null
        return
    }

    $ordered = Resolve-Conflicts -SelectedIds $selectedSimple

    $restorePointHandledSeparately = (-not $Undo -and $ChkRestorePoint.IsChecked)
    if ($restorePointHandledSeparately) {
        $ordered = @($ordered | Where-Object { $_ -ne 'EXT-001' })
        $rp = $AllTweaks | Where-Object { $_.id -eq 'EXT-001' }
        if ($rp) { Invoke-TweakEngine -Tweak $rp | Out-Null }
    }

    $totalItems = [Math]::Max($ordered.Count + $selectedLeveled.Count, 1)
    $i = 0
    $BtnApply.IsEnabled = $false
    $BtnUndo.IsEnabled = $false
    $BtnWelcomeApply.IsEnabled = $false
    $BtnWelcomeUndo.IsEnabled = $false
    $WelcomeCompletionText.Text = "Aplicando... aguarde."

    $engineCtx = New-EngineContext
    $txn = New-Transaction
    $criticalFailure = $null

    foreach ($id in $ordered) {
        $i++
        $pct = [double]($i / $totalItems) * 100
        $ProgBar.Value = $pct
        $WelcomeProgBar.Value = $pct
        $tweak = $AllTweaks | Where-Object { $_.id -eq $id }
        $tr = Invoke-Tweak -Tweak $tweak -Action $(if ($Undo) { 'Undo' } else { 'Apply' }) -Context $engineCtx
        $ok = $tr.Success
        if ($ok -and -not $script:SimulationMode) {
            if ($Undo) { $AppliedState.Remove($id) } else { $AppliedState[$id] = (Get-Date -Format 'o'); Add-TransactionStep -Transaction $txn -Tweak $tweak }
        }
        if (-not $ok -and -not $Undo -and $tweak.risk -eq 'Alto') {
            $criticalFailure = $tweak.id
            [System.Windows.Forms.Application]::DoEvents()
            break
        }
        [System.Windows.Forms.Application]::DoEvents()
    }
    if (-not $criticalFailure) {
        foreach ($id in $selectedLeveled) {
            $i++
            $pct = [double]($i / $totalItems) * 100
            $ProgBar.Value = $pct
            $WelcomeProgBar.Value = $pct
            $tweak = $AllTweaks | Where-Object { $_.id -eq $id }
            $lvl = $LevelSelections[$id]
            $tr = Invoke-Tweak -Tweak $tweak -Action $(if ($Undo) { 'Undo' } else { 'Apply' }) -Level $lvl -Context $engineCtx
            $ok = $tr.Success
            if ($ok -and -not $Undo -and -not $script:SimulationMode) { $AppliedState[$id] = (Get-Date -Format 'o'); Add-TransactionStep -Transaction $txn -Tweak $tweak -Level $lvl }
            if ($ok -and $Undo -and -not $script:SimulationMode) { $AppliedState.Remove($id); $LevelSelections[$id] = 0 }
            if (-not $ok -and -not $Undo -and $tweak.risk -eq 'Alto') {
                $criticalFailure = $tweak.id
                [System.Windows.Forms.Application]::DoEvents()
                break
            }
            [System.Windows.Forms.Application]::DoEvents()
        }
    }

    if ($criticalFailure -and -not $script:SimulationMode) {
        Invoke-TransactionRollback -Transaction $txn
        foreach ($step in $txn.Steps) { $AppliedState.Remove($step.Tweak.id) }
    }

    if (-not $Undo -and -not $script:SimulationMode -and -not $criticalFailure) { try { Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Start-Process explorer.exe } catch { } }

    if (-not $script:SimulationMode) { Save-State; Save-Rollback }
    $BtnApply.IsEnabled = $true
    $BtnUndo.IsEnabled = $true
    $BtnWelcomeApply.IsEnabled = $true
    $BtnWelcomeUndo.IsEnabled = $true
    $ProgBar.Value = 0
    $WelcomeProgBar.Value = 0
    if ($criticalFailure) {
        $WelcomeCompletionText.Text = "⚠️ Interrompido — $criticalFailure (risco Alto) falhou. Os itens já aplicados neste lote foram revertidos automaticamente."
        [System.Windows.MessageBox]::Show("O tweak '$criticalFailure' (risco Alto) falhou ao aplicar.`n`nPor segurança, todos os outros itens já aplicados NESTE lote foram revertidos automaticamente (ordem inversa). Veja o log para detalhes.", "Win-Slim Suite - Aplicação interrompida", 'OK', 'Warning') | Out-Null
        Render-Tweaks -Category $CategoryList.SelectedItem -Filter $TxtSearch.Text
        return
    }
    $action = if ($Undo) { 'revertidos (rollback profissional aplicado quando havia snapshot salvo)' } else { 'aplicados' }
    $reinicieMsg = ' Reinicie para garantir efeito completo.'
    if ($script:SimulationMode) { $action = 'simulados (SIMULAÇÃO — nada foi alterado de verdade, veja o log)'; $reinicieMsg = '' }
    $WelcomeCompletionText.Text = "✅ Concluído — $totalItems tweaks $action.$reinicieMsg"
    $msgBody = "$totalItems tweaks $action. Veja o log para detalhes."
    if ($script:SimulationMode) {
        $msgBody += "`n`n🧪 Modo Simulação estava ativo: nenhuma alteração real foi feita."
    } else {
        $msgBody += " Reinicie o computador para garantir que todas as mudanças tenham efeito completo."
    }
    [System.Windows.MessageBox]::Show($msgBody, "Win-Slim Suite", 'OK', 'Information') | Out-Null
    Render-Tweaks -Category $CategoryList.SelectedItem -Filter $TxtSearch.Text
}

function Update-SimulationModeUI {
    if ($script:SimulationMode) {
        $BtnApply.Content = '🧪 Simular Aplicação (nada será alterado)'
        $BtnUndo.Content = '🧪 Simular Desfazer'
        if ($BtnMaintApply) { $BtnMaintApply.Content = '🧪 Simular selecionadas' }
        if ($BtnWelcomeApply) { $BtnWelcomeApply.Content = '🧪 Simular Perfil' }
        if ($BtnWelcomeUndo) { $BtnWelcomeUndo.Content = '🧪 Simular Rollback' }
        Write-Log 'Modo Simulação ATIVADO — nenhuma alteração real será feita até desmarcar.' 'SIM'
    } else {
        $BtnApply.Content = 'Aplicar Selecionados'
        $BtnUndo.Content = '↺ Rollback (Desfazer)'
        if ($BtnMaintApply) { $BtnMaintApply.Content = '▶  Aplicar selecionadas' }
        if ($BtnWelcomeApply) { $BtnWelcomeApply.Content = '✓ Aplicar Perfil' }
        if ($BtnWelcomeUndo) { $BtnWelcomeUndo.Content = '↺ Rollback' }
        Write-Log 'Modo Simulação desativado — Aplicar/Desfazer voltam a alterar o sistema de verdade.' 'INFO'
    }
}
$ChkSimulationMode.Add_Checked({ $script:SimulationMode = $true; Update-SimulationModeUI })
$ChkSimulationMode.Add_Unchecked({ $script:SimulationMode = $false; Update-SimulationModeUI })

