Write-Log "Win-Slim Suite v2.2 iniciado. Windows $($WinVersion) build $($WinBuild). $($VisibleTweaks.Count) tweaks carregados."

# ============================================================================
# 14. EXIBIR JANELA
# ============================================================================
# Rede de segurança final: qualquer exceção que escape de um handler de evento
# da UI (o equivalente ao Application.DispatcherUnhandledException do WPF, que
# apenas encaminha para Dispatcher.UnhandledException) é registrada e mostrada
# ao usuário em vez de derrubar o processo.
$Window.Dispatcher.Add_UnhandledException({
    param($sender, $e)
    try {
        $ex = $e.Exception
        Write-Log "Erro não tratado na interface: $($ex.GetType().Name): $($ex.Message)`n$($ex.StackTrace)" 'ERROR'
        $details = "Tipo: $($ex.GetType().FullName)`nMensagem: $($ex.Message)`n`n$($ex.StackTrace)"
        Show-FriendlyError -Title 'Win-Slim Suite - Erro inesperado' -Icon 'Error' -Summary ((Get-FriendlyErrorSummary -Exception $ex) + ' O programa continua aberto.') -Details $details
    } catch { }
    $e.Handled = $true
})

try {
    $Window.ShowDialog() | Out-Null
} catch {
    Write-Log "Erro fatal na janela principal: $($_.Exception.Message)" 'ERROR'
    Show-FriendlyError -Title 'Win-Slim Suite - Erro grave' -Icon 'Error' -Summary 'O programa encontrou um erro grave e precisa fechar. Nenhuma alteração parcial fica sem registro: veja o log para saber o que já foi aplicado.' -Details (Format-ExceptionDetails -ErrorRecord $_)
}
